cat > ridehistory.go <<'EOF'
package location

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"go.opentelemetry.io/otel/attribute"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
)

// errRideNotFound is returned when updating a ride history entry that doesn't exist.
var errRideNotFound = errors.New("ride history entry not found")

const rideHistoryColumns = "id, pickup_location, dropoff_location, request_time, driver_plate, fare"

func (d *database) traceQuery(ctx context.Context, query string) trace.Span {
	_, span := d.tracer.Start(ctx, "SQL "+query[:6], trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.Key("sql.query").String(query),
	)
	return span
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanRide(row rowScanner) (RideHistoryEntry, error) {
	var (
		e    RideHistoryEntry
		fare sql.NullFloat64
	)
	if err := row.Scan(&e.ID, &e.PickupLocation, &e.DropoffLocation, &e.RequestTime, &e.DriverPlate, &fare); err != nil {
		return e, err
	}
	if fare.Valid {
		e.Fare = &fare.Float64
	}
	e.RequestTime = e.RequestTime.UTC()
	return e, nil
}

// ListRideHistory returns all rides, most recent first, together with their count.
func (d *database) ListRideHistory(ctx context.Context) (*RideHistory, error) {
	query := "SELECT " + rideHistoryColumns + " FROM ride_history ORDER BY request_time DESC, id DESC"
	defer d.traceQuery(ctx, query).End()

	rows, err := d.db.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	history := &RideHistory{Rides: []RideHistoryEntry{}}
	for rows.Next() {
		e, err := scanRide(rows)
		if err != nil {
			return nil, err
		}
		history.Rides = append(history.Rides, e)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	history.Total = len(history.Rides)
	return history, nil
}

// CreateRideHistory stores a new ride. A zero RequestTime defaults to now.
func (d *database) CreateRideHistory(ctx context.Context, entry *RideHistoryEntry) (*RideHistoryEntry, error) {
	query := "INSERT INTO ride_history (pickup_location, dropoff_location, request_time, driver_plate, fare) VALUES (?, ?, ?, ?, ?)"
	defer d.traceQuery(ctx, query).End()

	requestTime := entry.RequestTime
	if requestTime.IsZero() {
		requestTime = time.Now()
	}
	requestTime = requestTime.UTC().Truncate(time.Millisecond)

	res, err := d.db.ExecContext(ctx, query,
		entry.PickupLocation, entry.DropoffLocation, requestTime, entry.DriverPlate, entry.Fare)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	return d.getRideHistory(ctx, id)
}

// UpdateRideHistory sets the driver plate and fare of an existing ride.
func (d *database) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) (*RideHistoryEntry, error) {
	query := "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
	defer d.traceQuery(ctx, query).End()

	if _, err := d.db.ExecContext(ctx, query, update.DriverPlate, update.Fare, update.ID); err != nil {
		return nil, err
	}
	// RowsAffected can't tell "not found" from "unchanged", so read the row back.
	return d.getRideHistory(ctx, update.ID)
}

func (d *database) getRideHistory(ctx context.Context, id int64) (*RideHistoryEntry, error) {
	row := d.db.QueryRowContext(ctx, "SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", id)
	e, err := scanRide(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, errRideNotFound
	}
	if err != nil {
		return nil, err
