package config
import (
	"os"
)
func SignadotBaselineName() string {
	return os.Getenv("SIGNADOT_BASELINE_NAME")
}
func SignadotSandboxName() string {
	return os.Getenv("SIGNADOT_SANDBOX_NAME")
}
func SignadotSandboxRoutingKey() string {
	return os.Getenv("SIGNADOT_SANDBOX_ROUTING_KEY")
}
// This sets the consumer group with suffix '-' + <routing key>
// if running in fork.  otherwise, it just returns the argument.
func SignadotConsumerGroup(groupID string) string {
	sandboxRoutingKey := SignadotSandboxRoutingKey()
	if sandboxRoutingKey != "" {
		return groupID + "-" + sandboxRoutingKey
	}
	return groupID
}
package config
import (
	"strings"
)
func GetNamespace() string {
	return EnvDefault("SIGNADOT_BASELINE_NAMESPACE", "hotrod")
}
func ExpandNamespace(v string) string {
	return strings.ReplaceAll(v, "<NAMESPACE>", GetNamespace())
}
package config
func GetLocationBindPort() string {
	return EnvDefault("LOCATION_BIND_PORT", "8081")
}
func GetLocationAddr() string {
	return ExpandNamespace(EnvDefault("LOCATION_ADDR", "location:8081"))
}
package config
import (
	"os"
	"time"
)
func GetMySQLAddr() string {
	return ExpandNamespace(EnvDefault("MYSQL_ADDR", "mysql:3306"))
}
func GetMySQLUser() string {
	return EnvDefault("MYSQL_USER", "root")
}
func GetMySQLPassword() string {
	return EnvDefault("MYSQL_PASS", "")
}
func GetMySQLDatabaseName() string {
	return EnvDefault("MYSQL_DBNAME", "location")
}
// how long retrieving a location record takes.
func GetMySQLGetDelay() time.Duration {
	defaultDuration := 300 * time.Millisecond
	e := os.Getenv("MYSQL_GET_DELAY")
	if e == "" {
		return defaultDuration
	}
	dur, err := time.ParseDuration(e)
	if err != nil {
		return defaultDuration
	}
	return dur
}
// the standard deviation
func GetMySQLGetDelayStdDev() time.Duration {
	return GetMySQLGetDelay() / 10
}
