async (page) => {
  const K = '23n9s6btyq4dg';
  await page.unrouteAll();
  page.__patches = [];
  page.__errors = [];
  page.on('pageerror', e => page.__errors.push(String(e)));
  await page.route('**/*', async route => {
    const req = route.request();
    const headers = { ...req.headers(), baggage: req.headers()['baggage'] ? `${req.headers()['baggage']}, sd-routing-key=${K}` : `sd-routing-key=${K}`, tracestate: `sd-routing-key=${K}` };
    if (req.method() === 'PATCH' && req.url().includes('/ride-history')) {
      // environment workaround: inbound PATCH via the cluster URL isn't delivered to local mappings
      page.__patches.push({ url: req.url(), body: req.postData() });
      const resp = await route.fetch({ url: 'http://localhost:8080/ride-history', headers });
      page.__patches[page.__patches.length - 1].status = resp.status();
      return route.fulfill({ response: resp });
    }
    await route.continue({ headers });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  return { title: await page.title(), len: (await page.content()).length };
}

