    countdown: await cd.textContent(),
    total: await page.getByTestId('ride-history-total').textContent(),
    rows: await page.getByTestId('ride-history-row').allInnerTexts(),
    patches: page.__patches,
    pageErrors: page.__errors,
  };
}

